const initialRecipe={title:'Golden Garlic Toast',servings:'2 slices',time:'18 min',creator:'@milaeats',description:'A quick, buttery garlic toast with a crisp edge and a soft, herby center.',ingredients:[{name:'Sourdough bread',amount:'2 slices'},{name:'Unsalted butter',amount:'2 tbsp'},{name:'Garlic, finely grated',amount:'2 cloves'},{name:'Parsley, chopped',amount:'1 tbsp'},{name:'Parmesan, grated',amount:'2 tbsp'}],steps:[{title:'Build the garlic butter',description:'Mix softened butter with grated garlic, parsley, and Parmesan until evenly combined.',tip:'Let it sit for 30 seconds so the garlic can bloom.',clip:'mix',clipLabel:'Mixing garlic butter',materials:['2 tbsp butter','2 cloves garlic','1 tbsp parsley','2 tbsp Parmesan']},{title:'Spread edge to edge',description:'Spread the garlic butter all the way to the corners of each slice.',tip:'A thin, even layer gives you crisp edges without dry spots.',clip:'spread',clipLabel:'Spreading butter',materials:['2 slices sourdough','Garlic butter']},{title:'Toast until golden',description:'Place the slices on a tray and bake until the top is golden and the edges are crisp.',tip:'Keep an eye on the corners — they color first.',clip:'toast',clipLabel:'Toasting in the oven',materials:['Prepared toast','Oven at 400°F']},{title:'Finish and serve',description:'Top with a little parsley and serve while the toast is still warm.',tip:'A final sprinkle of Parmesan makes the finish extra savory.',clip:'finish',clipLabel:'Finishing with parsley',materials:['Toasted bread','Extra parsley','Extra Parmesan']}]};
const state={mode:'creator',screen:'publish',recipe:clone(initialRecipe),initialRecipe:clone(initialRecipe),guideAttached:false,processingStep:0,viewerStep:0,checkedIngredients:new Set(),clipPlaying:true,clipProgress:8,directoryOpen:false,timerSeconds:90,timerRunning:false,shareImage:0,sharePublished:false,editorError:false};
let processTimer,clipTimer,cookingTimer,toastTimer;
function clone(value){return JSON.parse(JSON.stringify(value))}
function esc(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]))}
function icon(name){const paths={arrow:'<path d="m9 18 6-6-6-6" />',back:'<path d="m15 18-6-6 6-6" />',check:'<path d="m5 12 4.2 4.2L19 6.5" />',clock:'<circle cx="12" cy="12" r="8.5" /><path d="M12 7v5l3.2 2" />',pause:'<path d="M9 6v12M15 6v12" />',play:'<path d="m9 6 9 6-9 6V6Z" />',replay:'<path d="M4.5 10a7.7 7.7 0 0 1 13.2-2.7L20 9.5M20 5.5v4h-4" /><path d="M19.5 14a7.7 7.7 0 0 1-13.2 2.7L4 14.5M4 18.5v-4h4" />',list:'<path d="M8 6h11M8 12h11M8 18h11" /><path d="M4 6h.01M4 12h.01M4 18h.01" />',heart:'<path d="M20 8.5c0 5-8 10-8 10s-8-5-8-10A4.5 4.5 0 0 1 12 6a4.5 4.5 0 0 1 8 2.5Z" />',comment:'<path d="M19 11.5a7 7 0 0 1-7 7 7.6 7.6 0 0 1-3.1-.7L5 19l1.2-3.3A7 7 0 1 1 19 11.5Z" />',share:'<path d="m20 4-7.2 16-2.4-7.2L3.2 10 20 4Z" /><path d="m10.4 12.8 4.4-4.4" />',settings:'<circle cx="12" cy="12" r="3" /><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-1.7 1.7-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.5v.2h-2.4v-.2a1.7 1.7 0 0 0-1-1.5 1.7 1.7 0 0 0-1.9.3l-.1.1-1.7-1.7.1-.1a1.7 1.7 0 0 0 .3-1.9 1.7 1.7 0 0 0-1.5-1H7v-2.4h.2a1.7 1.7 0 0 0 1.5-1 1.7 1.7 0 0 0-.3-1.9l-.1-.1L10 6.9l.1.1a1.7 1.7 0 0 0 1.9.3 1.7 1.7 0 0 0 1-1.5v-.2h2.4v.2a1.7 1.7 0 0 0 1 1.5 1.7 1.7 0 0 0 1.9-.3l.1-.1 1.7 1.7-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.5 1h.2V14h-.2a1.7 1.7 0 0 0-1.5 1Z" />'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||''}</svg>`}
function clipMarkup(step,extraClass=''){const visual=step.clip==='mix'?'<div class="bowl"></div><div class="spoon"></div><span class="visual-glyph">🧈</span>':step.clip==='spread'?'<div class="hand"></div><div class="toast-object"></div><span class="visual-glyph">🧄</span>':step.clip==='toast'?'<div class="oven"></div><span class="visual-glyph">🔥</span>':'<div class="toast-object"></div><span class="greenery">🌿</span>';return `<div class="clip-preview ${extraClass}" role="img" aria-label="Simulated video clip: ${esc(step.clipLabel)}"><div class="clip-visual ${esc(step.clip)}" style="--clip-image:url('./assets/cooking/${esc(step.clip)}.png')">${visual}</div><span class="clip-label">${esc(step.clipLabel)}</span></div>`}
function render(){stopClipTimer();stopCookingTimer();const isDark=['processing','posted','video','cook','complete'].includes(state.screen);document.querySelector('#app').innerHTML=`<div class="prototype-frame"><main class="phone-frame ${isDark?'is-dark':''}">${state.mode==='creator'?renderCreator():renderViewer()}</main><div class="toast" id="toast" role="status" aria-live="polite"></div></div>`;bindEvents();if(state.screen==='processing')scheduleProcessing();if(state.screen==='cook'&&state.clipPlaying)startClipTimer();if(state.screen==='cook'&&state.timerRunning)startCookingTimer()}
function renderCreator(){if(state.screen==='processing')return renderProcessing();if(state.screen==='editor')return renderEditor();if(state.screen==='creator-preview')return renderCreatorPreview();if(state.screen==='posted')return renderPosted();return renderCreatorPublish()}
function renderCreatorPublish(){return `<div class="screen-scroll creator-native figma-publish"><div class="publish-status">9:41 <span>▮▮▮ ◒ ▰</span></div><div class="publish-nav"><button class="nav-text-button nav-back" type="button" data-action="reset" aria-label="Close post composer">${icon('back')}</button><span></span><button class="nav-text-button nav-text-button-strong" type="button" data-action="publish-post">Post</button></div><section class="publish-media"><div class="publish-description"><textarea class="text-area" id="caption" data-edit="description" placeholder="Add description...">${esc(state.recipe.description)}</textarea><div class="publish-tags"><span># Hashtags</span><span>@ Mention</span></div></div><button class="cover-button" type="button"><span class="cover-image"></span><span>Edit cover</span></button></section><section class="publish-settings"><button class="publish-row" type="button"><span class="row-icon">⌖</span><span><strong>Add location</strong></span>${icon('arrow')}</button><button class="publish-row" type="button"><span class="row-icon">＋</span><span><strong>Add link</strong></span>${icon('arrow')}</button><button class="publish-row recipe-entry-row" type="button" data-action="${state.guideAttached?'edit-guide':'start-processing'}"><span class="row-icon">＋</span><span><strong>${state.guideAttached?'Recipe added':'Add recipe'}</strong><small>${state.guideAttached?'Viewers can follow along with this video':'Let viewers cook along with your video'}</small></span>${icon('arrow')}</button><button class="publish-row" type="button"><span class="row-icon">◉</span><span><strong>Everyone can view this post</strong></span>${icon('arrow')}</button><button class="publish-row" type="button"><span class="row-icon">•••</span><span><strong>More options</strong><small>Privacy and more settings</small></span>${icon('arrow')}</button><div class="publish-share-row"><span><strong>Share to</strong></span>${icon('arrow')}</div></section><div class="publish-footer"><button class="draft-button" type="button" data-action="back-to-creator">Drafts</button><button class="primary-button publish-submit" type="button" data-action="publish-post">Post</button></div></div>`}
function renderAttachedGuide(){return `<div class="guide-entry" style="margin-bottom:.25rem"><span class="guide-entry-copy"><span class="guide-entry-icon">✓</span><span><strong>${esc(state.recipe.title)}</strong><small>${state.recipe.steps.length} steps · ${esc(state.recipe.time)} · Attached</small></span></span><button class="text-button" type="button" data-action="remove-guide">Remove</button></div><div class="button-row"><button class="secondary-button" type="button" data-action="edit-guide">Edit guide</button><button class="secondary-button" type="button" data-action="preview-guide">Preview</button></div>`}
function renderProcessing(){const labels=['Identifying ingredients','Organizing steps','Matching video clips'];return `<section class="processing-screen"><div class="eyebrow">AI guide draft</div><h1>Finding the rhythm<br />inside your video.</h1><div class="processing-list">${labels.map((label,index)=>`<div class="processing-item ${index<state.processingStep?'is-done':''} ${index===state.processingStep?'is-current':''}"><span class="processing-dot">${index<state.processingStep?'✓':index===state.processingStep?'·':''}</span><span>${label}</span></div>`).join('')}</div><p class="processing-foot">AI generation is simulated for this prototype.<br />You will review every detail before attaching the guide.</p></section>`}
function renderEditor(){return `<div class="screen-scroll"><div class="topline"><button class="back-button" type="button" data-action="back-publish" aria-label="Back to publish page">${icon('back')}</button><div><div class="eyebrow pink">Review & edit</div><p class="topline-title">Step-by-step guide</p></div><span class="draft-badge">AI draft</span></div><div class="editor-head"><h1>Make it yours.</h1><p>Review what AI found, then fill in anything only you would know.</p></div><section class="page-pad"><div class="editor-section"><h2>Guide details</h2><label class="input-label" for="recipe-title">Recipe name</label><input class="text-input" id="recipe-title" data-edit="title" value="${esc(state.recipe.title)}" /><div class="field-row"><div><label class="input-label" for="servings">Serves</label><input class="text-input" id="servings" data-edit="servings" value="${esc(state.recipe.servings)}" /></div><div><label class="input-label" for="total-time">Total time</label><input class="text-input" id="total-time" data-edit="time" value="${esc(state.recipe.time)}" /></div></div></div><div class="editor-section"><h2>Ingredients</h2>${state.recipe.ingredients.map((ingredient,index)=>`<div class="field-row" style="margin-top:${index?'.65rem':'0'}"><input class="text-input" aria-label="Ingredient ${index+1} name" data-ingredient="${index}" data-key="name" value="${esc(ingredient.name)}" /><input class="text-input" aria-label="Ingredient ${index+1} amount" data-ingredient="${index}" data-key="amount" value="${esc(ingredient.amount)}" /></div>`).join('')}</div><div class="editor-section"><h2>Steps <span style="color:var(--muted);font-size:.7rem;font-family:'DM Sans',sans-serif">· ${state.recipe.steps.length} clips matched</span></h2>${state.recipe.steps.map((step,index)=>renderStepEditor(step,index)).join('')}</div><div class="sticky-action"><div class="button-row"><button class="secondary-button" type="button" data-action="preview-guide">Preview</button><button class="primary-button" type="button" data-action="confirm-guide"><span class="button-dot"></span>Confirm guide</button></div></div></section></div>`}
function renderStepEditor(step,index){const missing=index===2&&!step.temperature;return `<article class="step-editor"><div class="step-editor-top"><span class="step-number">${index+1}</span><strong>Step ${index+1}</strong></div><div class="step-preview-row"><div class="mini-clip">${clipMarkup(step)}</div><span class="mini-clip-label">${esc(step.clipLabel)}<br />Matched from 0:${String(index*4+3).padStart(2,'0')}–0:${String(index*4+7).padStart(2,'0')}</span></div><label class="input-label" for="step-title-${index}">Step name</label><input class="text-input" id="step-title-${index}" data-step="${index}" data-key="title" value="${esc(step.title)}" /><label class="input-label" for="step-description-${index}">What to do</label><textarea class="text-area" id="step-description-${index}" data-step="${index}" data-key="description">${esc(step.description)}</textarea>${index===2?`<div class="needs-input"><div class="needs-input-head"><span></span>Needs your input</div><p>AI heard “place in the oven,” but the temperature is not in the video. Add it before publishing.</p><label class="input-label" for="temperature">Oven temperature</label><input class="text-input" id="temperature" data-step="${index}" data-key="temperature" placeholder="e.g. 400°F" value="${esc(step.temperature||'')}" />${state.editorError&&missing?'<p class="error-note">Add the oven temperature to continue.</p>':''}</div>`:''}</article>`}
function renderCreatorPreview(){const first=state.recipe.steps[0];return `<div class="screen-scroll creator-preview"><div class="topline"><button class="back-button" type="button" data-action="back-editor" aria-label="Back to editor">${icon('back')}</button><div><div class="eyebrow pink">Preview</div><p class="topline-title">Viewer experience</p></div><span class="topline-meta">As posted</span></div><div class="preview-shell"><div class="preview-top"><span>FOLLOW ALONG</span><span>${state.recipe.steps.length} steps</span></div><div class="preview-content">${clipMarkup(first)}<h2>${esc(state.recipe.title)}</h2><p class="preview-meta">${esc(state.recipe.servings)} · ${esc(state.recipe.time)} · by ${esc(state.recipe.creator)}</p><div class="preview-section"><div class="eyebrow" style="color:var(--cyan)">Ingredients</div><p>${state.recipe.ingredients.slice(0,3).map(item=>`${esc(item.amount)} ${esc(item.name.toLowerCase())}`).join(' · ')}</p></div><div class="preview-section"><div class="eyebrow" style="color:var(--cyan)">First step</div><p><strong>${esc(first.title)}</strong></p><p style="color:#aaa">${esc(first.description)}</p></div></div></div><div class="page-pad"><div class="sticky-action"><div class="button-row"><button class="secondary-button" type="button" data-action="back-editor">Back to edit</button><button class="primary-button" type="button" data-action="confirm-guide"><span class="button-dot"></span>Confirm guide</button></div></div></div></div>`}
function renderPosted(){return `<section class="posted-screen"><div class="posted-icon">${icon('check')}</div><div class="eyebrow" style="margin-top:1.4rem;color:var(--cyan)">Published · simulated</div><h1>Your guide is<br />in the post.</h1><p>Viewers can now open “Follow along” and cook through your steps at their own pace.</p><div class="button-row"><button class="secondary-button" type="button" data-action="back-to-creator">Back to create</button><button class="primary-button" type="button" data-action="view-post"><span class="button-dot"></span>View post</button></div></section>`}
function renderViewer(){if(state.screen==='video')return renderViewerVideo();if(state.screen==='overview')return renderOverview();if(state.screen==='cook')return renderCook();if(state.screen==='complete')return renderComplete();if(state.screen==='share')return renderShare();return renderViewerVideo()}
function renderViewerVideo(){return `<section class="viewer-video"><div class="full-clip">${clipMarkup(state.recipe.steps[0])}</div><div class="video-topbar"><button class="video-live-button" type="button" data-action="reset" aria-label="Close video"><span class="live-dot"></span>LIVE</button><div class="video-tabs"><span>Following</span><strong>For You</strong></div><button class="video-search" type="button" aria-label="Search">⌕</button></div><div class="video-actions"><div class="video-action"><span class="circle creator-avatar"></span><span class="follow-plus">+</span></div><div class="video-action"><span class="circle">${icon('heart')}</span><span>48.2K</span></div><div class="video-action"><span class="circle">${icon('comment')}</span><span>612</span></div><div class="video-action"><span class="circle rail-symbol">▯</span><span>671</span></div><div class="video-action"><span class="circle">${icon('share')}</span><span>81.6K</span></div><div class="video-action sound-action"><span class="sound-disc">♫</span><span>original sound</span></div></div><div class="video-caption"><div class="video-author-line"><strong>${esc(state.recipe.creator)}</strong><span> · </span><span>Follow</span></div><p>${esc(state.recipe.description)} <strong>#garlictoast</strong> <strong>#cookwithme</strong></p><button class="follow-button" type="button" data-action="open-guide"><span class="follow-dot">✦</span><span><strong>Follow along</strong><small>${state.recipe.steps.length} steps · synced to video</small></span>${icon('arrow')}</button></div><div class="video-bottom-nav"><span>Home</span><span>Friends</span><span class="create-pill">+</span><span>Inbox</span><span>Profile</span></div><span class="home-indicator" aria-hidden="true"></span></section>`}
function renderOverview(){return `<div class="screen-scroll viewer-light"><div class="topline"><button class="back-button" type="button" data-action="back-to-video" aria-label="Back to video">${icon('back')}</button><div><div class="eyebrow pink">Follow along</div><p class="topline-title">Recipe guide</p></div><span class="topline-meta">${state.recipe.steps.length} steps</span></div><section class="overview-hero"><div class="recipe-photo"><span class="photo-garnish">🌿</span><span class="photo-stamp">From @milaeats</span></div><h1 class="overview-title">${esc(state.recipe.title)}</h1><div class="overview-author">by ${esc(state.recipe.creator)} · synced to the original video</div><div class="overview-meta"><span class="meta-chip"><strong>${esc(state.recipe.servings)}</strong><span>servings</span></span><span class="meta-chip"><strong>${esc(state.recipe.time)}</strong><span>total time</span></span><span class="meta-chip"><strong>${state.recipe.steps.length}</strong><span>steps</span></span></div></section><section class="page-pad"><div class="content-section"><div class="section-head"><h2>Get ready</h2><p>Tap to check off</p></div><div class="ingredient-list">${state.recipe.ingredients.map((item,index)=>`<label class="ingredient-row"><input type="checkbox" data-ingredient-check="${index}" ${state.checkedIngredients.has(index)?'checked':''} /><span class="ingredient-check">${icon('check')}</span><span class="ingredient-name">${esc(item.name)}</span><span class="ingredient-amount">${esc(item.amount)}</span></label>`).join('')}</div></div><div class="content-section"><div class="section-head"><h2>Steps</h2><p>Tap to preview</p></div><div class="step-overview-list">${state.recipe.steps.map((step,index)=>`<button class="step-overview-button" type="button" data-action="jump-step" data-step-index="${index}"><span class="step-index">${index+1}</span><span><strong>${esc(step.title)}</strong><small>${esc(step.clipLabel)}</small></span>${icon('arrow')}</button>`).join('')}</div></div><div class="sticky-action"><button class="primary-button" type="button" data-action="start-cooking"><span class="button-dot"></span>Start cooking</button></div></section></div>`}
function renderCook(){const step=state.recipe.steps[state.viewerStep];return `<div class="screen-scroll cook-screen"><div class="cook-top"><div class="cook-topline"><button type="button" data-action="back-to-overview">${icon('back')} Back to guide</button><span>${state.viewerStep+1} / ${state.recipe.steps.length}</span><button type="button" data-action="open-directory">Steps ${icon('list')}</button></div><div class="player"><div class="clip-preview">${clipMarkup(step)}</div><div class="player-overlay"><button class="play-pause" type="button" data-action="toggle-clip" aria-label="${state.clipPlaying?'Pause clip':'Play clip'}">${icon(state.clipPlaying?'pause':'play')}</button></div><div class="player-caption"><small>${esc(step.clipLabel)}</small><span class="clip-badge">Looping clip</span></div><div class="progress-track"><div class="progress-fill" id="clip-progress" style="width:${state.clipProgress}%"></div></div></div></div><div class="cook-copy"><div class="step-counter">Step ${state.viewerStep+1} · ${state.viewerStep===0?'Start here':'Keep going'}</div><h1>${esc(step.title)}</h1><p class="instruction">${esc(step.description)}</p><div class="tip-card"><span class="tip-icon">✦</span><span>${esc(step.tip)}</span></div><div class="step-materials"><h2>What you need for this step</h2><div class="material-pills">${step.materials.map(item=>`<span class="material-pill">${esc(item)}</span>`).join('')}</div></div>${state.viewerStep===2?renderTimer():''}</div><div class="cook-footer"><div class="button-row"><button class="secondary-button" type="button" data-action="previous-step" ${state.viewerStep===0?'disabled style="opacity:.4"':''}>Previous</button><button class="replay-button" type="button" data-action="replay-clip">${icon('replay')} Replay</button><button class="primary-button" type="button" data-action="next-step">${state.viewerStep===state.recipe.steps.length-1?'Finish':'Next'} ${icon('arrow')}</button></div></div>${state.directoryOpen?renderDirectory():''}</div>`}
function renderTimer(){return `<div class="timer-card"><div class="timer-card-head"><span>⏱ Baking timer</span><span>${state.timerRunning?'Running':state.timerSeconds===0?'Done':'Ready'}</span></div><div class="timer-value">${formatTime(state.timerSeconds)}</div><div class="timer-controls"><button type="button" data-action="toggle-timer">${state.timerRunning?'Pause':state.timerSeconds===0?'Done':'Start timer'}</button><button type="button" data-action="reset-timer">Reset</button></div></div>`}
function renderDirectory(){return `<div class="directory-backdrop"><div class="directory-sheet"><div class="sheet-handle"></div><div class="sheet-head"><h2>Step directory</h2><button class="sheet-close" type="button" data-action="close-directory">Close</button></div><div class="directory-list">${state.recipe.steps.map((step,index)=>`<button class="directory-item ${index===state.viewerStep?'is-current':''}" type="button" data-action="jump-step" data-step-index="${index}"><span class="directory-number">${index+1}</span><span><strong>${esc(step.title)}</strong><small>${esc(step.clipLabel)}</small></span><span class="directory-check">${index<state.viewerStep?'Done':index===state.viewerStep?'Now':''}</span></button>`).join('')}</div></div></div>`}
function renderComplete(){return `<section class="complete-screen"><div class="complete-visual"><span class="finish-emoji">🌿</span></div><div class="complete-check">${icon('check')}</div><h1>That’s a<br />golden finish.</h1><p>You made ${esc(state.recipe.title)} at your own pace.</p><div class="source-line">Recipe guide by ${esc(state.recipe.creator)} · simulated completion</div><div class="button-row"><button class="secondary-button" type="button" data-action="share-result">Share your result</button><button class="primary-button" type="button" data-action="back-to-video"><span class="button-dot"></span>Back to video</button></div></section>`}
function renderShare(){if(state.sharePublished)return `<section class="share-screen"><div class="share-success"><div class="posted-icon">${icon('check')}</div><h2>Shared, your way.</h2><p>Your result is ready with the original guide linked automatically.</p><button class="primary-button" type="button" data-action="back-to-video">Back to video</button></div></section>`;return `<section class="share-screen"><div class="topline" style="padding-left:0;padding-right:0"><button class="back-button" type="button" data-action="back-to-complete" aria-label="Back to completion">${icon('back')}</button><div><div class="eyebrow pink">Optional</div><p class="topline-title">Share your result</p></div><span class="topline-meta">Preview</span></div><h1>Show your<br />golden finish.</h1><p class="intro">Choose a cover and add a note. Sharing is optional — your guide is already complete.</p><div class="share-options">${[0,1].map(image=>`<button class="share-choice ${state.shareImage===image?'is-selected':''}" type="button" data-action="select-share-image" data-share-image="${image}"><span class="choice-dish"></span><span class="choice-toast"></span><span>${image===0?'Warm & crisp':'Fresh from the oven'}</span><span class="choice-check">${state.shareImage===image?'✓':''}</span></button>`).join('')}</div><label class="input-label" for="share-caption">Caption</label><textarea class="text-area" id="share-caption">Made it through the Follow along guide ✨</textarea><div class="sticky-action"><button class="primary-button" type="button" data-action="publish-share"><span class="button-dot"></span>Share result</button></div></section>`}
function bindEvents(){const app=document.querySelector('#app');app.addEventListener('click',handleClick);app.addEventListener('input',handleInput);app.addEventListener('change',handleChange)}
function handleClick(event){const modeButton=event.target.closest('[data-mode]');if(modeButton){state.mode=modeButton.dataset.mode;state.screen=state.mode==='creator'?'publish':'video';state.directoryOpen=false;render();return}const action=event.target.closest('[data-action]');if(!action)return;const name=action.dataset.action;if(name==='reset')return reset();if(name==='start-processing')return startProcessing();if(name==='back-publish')return go('publish');if(name==='back-editor')return go('editor');if(name==='edit-guide')return go('editor');if(name==='preview-guide')return go('creator-preview');if(name==='remove-guide'){state.guideAttached=false;toast('Guide removed from this post.');return render()}if(name==='confirm-guide')return confirmGuide();if(name==='publish-post')return publishPost();if(name==='back-to-creator'){state.mode='creator';return go('publish')}if(name==='view-post'){state.mode='viewer';return go('video')}if(name==='open-guide'){state.mode='viewer';return go('overview')}if(name==='back-to-video'){state.mode='viewer';return go('video')}if(name==='back-to-overview')return go('overview');if(name==='start-cooking'){state.viewerStep=0;state.clipProgress=4;state.clipPlaying=true;return go('cook')}if(name==='toggle-clip'){state.clipPlaying=!state.clipPlaying;return render()}if(name==='replay-clip'){state.clipProgress=0;state.clipPlaying=true;return render()}if(name==='previous-step'){state.viewerStep=Math.max(0,state.viewerStep-1);state.clipProgress=0;state.clipPlaying=true;return render()}if(name==='next-step'){if(state.viewerStep>=state.recipe.steps.length-1){state.timerRunning=false;return go('complete')}state.viewerStep+=1;state.clipProgress=0;state.clipPlaying=true;return render()}if(name==='open-directory'){state.directoryOpen=true;return render()}if(name==='close-directory'){state.directoryOpen=false;return render()}if(name==='jump-step'){state.viewerStep=Number(action.dataset.stepIndex);state.directoryOpen=false;state.clipProgress=0;state.clipPlaying=true;return go('cook')}if(name==='toggle-timer'){if(state.timerSeconds===0)return;state.timerRunning=!state.timerRunning;return render()}if(name==='reset-timer'){state.timerSeconds=90;state.timerRunning=false;return render()}if(name==='share-result'){state.sharePublished=false;return go('share')}if(name==='back-to-complete')return go('complete');if(name==='select-share-image'){state.shareImage=Number(action.dataset.shareImage);return render()}if(name==='publish-share'){state.sharePublished=true;return render()}}
function handleInput(event){const el=event.target;if(el.dataset.edit)state.recipe[el.dataset.edit]=el.value;if(el.dataset.ingredient!==undefined)state.recipe.ingredients[Number(el.dataset.ingredient)][el.dataset.key]=el.value;if(el.dataset.step!==undefined){state.recipe.steps[Number(el.dataset.step)][el.dataset.key]=el.value;if(el.dataset.key==='temperature')state.editorError=false}}
function handleChange(event){const checkbox=event.target.closest('[data-ingredient-check]');if(!checkbox)return;const index=Number(checkbox.dataset.ingredientCheck);if(checkbox.checked)state.checkedIngredients.add(index);else state.checkedIngredients.delete(index)}
function go(screen){state.screen=screen;state.directoryOpen=false;render()}
function startProcessing(){clearTimeout(processTimer);state.screen='processing';state.processingStep=0;render()}
function scheduleProcessing(){clearTimeout(processTimer);if(state.processingStep<3)processTimer=setTimeout(()=>{state.processingStep+=1;if(state.processingStep>=3){state.screen='editor';render()}else render()},720)}
function confirmGuide(){const temperature=state.recipe.steps[2].temperature;if(!temperature||!temperature.trim()){state.editorError=true;state.screen='editor';render();setTimeout(()=>document.querySelector('#temperature')?.focus(),0);return}state.editorError=false;state.guideAttached=true;state.screen='publish';render();setTimeout(()=>toast('Guide confirmed — ready to attach.'),0)}
function publishPost(){state.screen='posted';render()}
function startClipTimer(){clearInterval(clipTimer);clipTimer=setInterval(()=>{if(!state.clipPlaying||state.screen!=='cook')return;state.clipProgress+=.9;if(state.clipProgress>=100)state.clipProgress=0;const progress=document.querySelector('#clip-progress');if(progress)progress.style.width=`${state.clipProgress}%`},120)}
function stopClipTimer(){clearInterval(clipTimer);clipTimer=undefined}
function startCookingTimer(){clearInterval(cookingTimer);cookingTimer=setInterval(()=>{if(!state.timerRunning||state.timerSeconds<=0)return;state.timerSeconds-=1;if(state.timerSeconds<=0){state.timerSeconds=0;state.timerRunning=false}const timer=document.querySelector('.timer-value');const status=document.querySelector('.timer-card-head span:last-child');if(timer)timer.textContent=formatTime(state.timerSeconds);if(status)status.textContent=state.timerRunning?'Running':state.timerSeconds===0?'Done':'Ready'},1000)}
function stopCookingTimer(){clearInterval(cookingTimer);cookingTimer=undefined}function formatTime(seconds){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}
function toast(message){const node=document.querySelector('#toast');if(!node)return;node.textContent=message;node.classList.add('is-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('is-visible'),2200)}
function reset(){clearTimeout(processTimer);stopClipTimer();stopCookingTimer();state.mode='creator';state.screen='publish';state.recipe=clone(state.initialRecipe);state.guideAttached=false;state.processingStep=0;state.viewerStep=0;state.checkedIngredients=new Set();state.clipPlaying=true;state.clipProgress=8;state.directoryOpen=false;state.timerSeconds=90;state.timerRunning=false;state.shareImage=0;state.sharePublished=false;state.editorError=false;render()}
initialRecipe.title='Garlic butter toast';initialRecipe.servings='2';initialRecipe.time='15 min';initialRecipe.creator='@ellacooks';initialRecipe.description='Crispy garlic butter toast 🧄';applyExploreBData();state.initialRecipe=clone(initialRecipe);state.recipe=clone(initialRecipe);state.timerSeconds=480;state.ingredientsOpen=false;state.shareStage='picker';state.shareCaption='Made it through the Cook with me guide ✨';render();

// Figma-aligned surface overrides. The interaction/state model above remains unchanged.
function renderCreatorPublish(){return `<div class="screen-scroll creator-native figma-publish"><div class="publish-status"><span>9:41</span><span>▮▮▮ ◒ ▰</span></div><div class="publish-nav"><button class="nav-text-button nav-back" type="button" data-action="reset" aria-label="Close post composer">${icon('back')}</button><span></span><button class="nav-text-button nav-text-button-strong" type="button" data-action="publish-post">Post</button></div><section class="publish-media"><div class="publish-description"><textarea class="text-area" id="caption" data-edit="description" placeholder="Add description...">${esc(state.recipe.description)}</textarea><div class="publish-tags"><span># Hashtags</span><span>@ Mention</span></div></div><button class="cover-button" type="button"><span class="cover-image"></span><span>Edit cover</span></button></section><section class="publish-settings"><button class="publish-row" type="button"><span class="row-icon">⌖</span><span><strong>Add location</strong></span>${icon('arrow')}</button><button class="publish-row" type="button"><span class="row-icon">＋</span><span><strong>Add link</strong></span>${icon('arrow')}</button><button class="publish-row recipe-entry-row" type="button" data-action="${state.guideAttached?'edit-guide':'start-processing'}"><span class="row-icon">＋</span><span><strong>${state.guideAttached?'Recipe added':'Add step-by-step guide'}</strong><small>${state.guideAttached?'Viewers can follow along with this video':'Let viewers cook along with your video'}</small></span>${icon('arrow')}</button><button class="publish-row" type="button"><span class="row-icon">◉</span><span><strong>Everyone can view this post</strong></span>${icon('arrow')}</button><button class="publish-row" type="button"><span class="row-icon">•••</span><span><strong>More options</strong><small>Privacy and more settings</small></span>${icon('arrow')}</button><div class="publish-share-row"><span><strong>Share to</strong></span>${icon('arrow')}</div></section><div class="publish-footer"><button class="draft-button" type="button" data-action="back-to-creator">Drafts</button><button class="primary-button publish-submit" type="button" data-action="publish-post">Post</button></div></div>`}
function renderViewerVideo(){return `<section class="viewer-video figma-video"><div class="full-clip">${clipMarkup(state.recipe.steps[0])}</div><div class="video-topbar"><button class="video-live-button" type="button" data-action="reset" aria-label="Close video"><span class="live-dot"></span>LIVE</button><div class="video-tabs"><span>Following</span><strong>For You</strong></div><button class="video-search" type="button" aria-label="Search">⌕</button></div><div class="video-actions"><div class="video-action"><span class="circle creator-avatar"></span><span class="follow-plus">+</span></div><div class="video-action"><span class="circle">${icon('heart')}</span><span>3.1M</span></div><div class="video-action"><span class="circle">${icon('comment')}</span><span>45.4K</span></div><div class="video-action"><span class="circle rail-symbol">▯</span><span>233.8K</span></div><div class="video-action"><span class="circle">${icon('share')}</span><span>183.9K</span></div><div class="video-action sound-action"><span class="sound-disc">♫</span><span>original sound</span></div></div><div class="video-caption"><div class="video-author-line"><strong>${esc(state.recipe.creator)}</strong><span> · </span><span>Follow</span></div><p>${esc(state.recipe.description)} <strong>#easyrecipe #cookwithme</strong></p><button class="follow-button" type="button" data-action="open-guide"><span class="follow-dot">✦</span><span><strong>Follow along</strong><small>${state.recipe.steps.length} steps · synced to video</small></span>${icon('arrow')}</button></div><div class="video-bottom-nav"><span>Home</span><span>Friends <b class="nav-badge">5</b></span><span class="create-pill">+</span><span>Inbox <b class="nav-badge">23</b></span><span>Profile</span></div><span class="home-indicator" aria-hidden="true"></span></section>`}
function renderOverview(){return `<div class="screen-scroll recipe-screen"><div class="recipe-hero"><div class="recipe-hero-top"><button class="recipe-back" type="button" data-action="back-to-video" aria-label="Back to video">${icon('back')}</button><span class="recipe-kicker">Follow along</span><button class="recipe-more" type="button" aria-label="More options">•••</button></div><div class="recipe-hero-copy"><h1>${esc(state.recipe.title)}</h1><p>By ${esc(state.recipe.creator)}</p></div></div><section class="recipe-body"><button class="recipe-start" type="button" data-action="start-cooking">Start cooking</button><p class="recipe-description">A simple, crisp and buttery toast you can make alongside the original video.</p><div class="recipe-stats"><span><strong>Total time</strong><b>${esc(state.recipe.time)}</b></span><span><strong>Servings</strong><b>${esc(state.recipe.servings)} people</b></span></div><div class="recipe-section-head"><h2>Ingredients</h2><div class="servings-stepper"><button type="button" aria-label="Decrease servings">−</button><span>${esc(state.recipe.servings)} servings</span><button type="button" aria-label="Increase servings">+</button></div></div><div class="recipe-ingredients">${state.recipe.ingredients.map((item,index)=>`<label class="recipe-ingredient"><input type="checkbox" data-ingredient-check="${index}" ${state.checkedIngredients.has(index)?'checked':''}/><span class="recipe-check">${icon('check')}</span><span>${esc(item.name)}</span><b>${esc(item.amount)}</b></label>`).join('')}</div><div class="recipe-section-head steps-heading"><h2>Steps</h2><span>${state.recipe.steps.length} steps</span></div><div class="recipe-steps">${state.recipe.steps.map((step,index)=>`<button class="recipe-step" type="button" data-action="jump-step" data-step-index="${index}"><span>${index+1}</span><strong>${esc(step.title)}</strong>${icon('arrow')}</button>`).join('')}</div></section></div>`}
function renderCook(){const step=state.recipe.steps[state.viewerStep];return `<div class="screen-scroll cook-figma"><div class="cook-figma-top"><button type="button" data-action="back-to-overview" aria-label="Back to guide">${icon('back')}</button><strong>Follow along</strong><button type="button" data-action="open-directory" aria-label="Open steps">•••</button></div><div class="cook-subtitle">${esc(state.recipe.title)} · ${esc(state.recipe.servings)} servings</div><div class="cook-step-label">Step ${state.viewerStep+1} of ${state.recipe.steps.length}</div><section class="cook-step-card"><div class="cook-step-number">${state.viewerStep+1}</div><div><h1>${esc(step.title)}</h1><p>${esc(step.description)}</p></div></section><div class="cook-media"><div class="cook-media-image">${clipMarkup(step)}</div><button class="cook-replay" type="button" data-action="replay-clip">${icon('replay')} Replay</button><span class="cook-media-time">00:08–00:24 · Tap to replay / loop</span><button class="cook-play" type="button" data-action="toggle-clip" aria-label="${state.clipPlaying?'Pause clip':'Play clip'}">${icon(state.clipPlaying?'pause':'play')}</button></div><section class="cook-details"><h2>Your steps</h2><div class="cook-step-list">${state.recipe.steps.map((item,index)=>`<button type="button" class="cook-step-row ${index===state.viewerStep?'is-current':''}" data-action="jump-step" data-step-index="${index}"><span>${index+1}</span><strong>${esc(item.title)}</strong><small>${index<state.viewerStep?'Done':index===state.viewerStep?'Now':'Up next'}</small></button>`).join('')}</div>${state.viewerStep===2?renderTimer():''}</section><div class="cook-figma-footer"><button type="button" class="ingredients-button" data-action="open-directory">Ingredients</button><button type="button" class="next-step-button" data-action="next-step">${state.viewerStep===state.recipe.steps.length-1?'Finish':'Next step'} ${icon('arrow')}</button></div>${state.directoryOpen?renderDirectory():''}</div>`}
function renderComplete(){return `<section class="complete-figma"><div class="complete-figma-top"><button type="button" data-action="back-to-video" aria-label="Back to video">${icon('back')}</button><span>Follow along</span><span></span></div><div class="complete-copy"><h1>You made it!</h1><p>One saved video. One real-life win.</p></div><div class="complete-image"></div><div class="complete-result-copy"><h2>Made it? Make it yours.</h2><p>Share your result with the original guide attached automatically. It’s optional — your cooking journey is complete either way.</p></div><div class="complete-actions"><button type="button" class="complete-primary" data-action="share-result">Post your result</button><button type="button" class="complete-secondary" data-action="back-to-video">Back to video</button></div></section>`}

function applyExploreBData(){initialRecipe.ingredients=[{name:'Sourdough',baseValue:2,unit:'thick slices',amount:'2 thick slices'},{name:'Softened butter',baseValue:2,unit:'tbsp',amount:'2 tbsp'},{name:'Garlic',baseValue:2,unit:'cloves, minced',amount:'2 cloves, minced'},{name:'Parsley',baseValue:1,unit:'tbsp, chopped',amount:'1 tbsp, chopped'}];initialRecipe.steps=[{title:'Slice the bread',description:'Cut 2 thick slices of sourdough.',tip:'Use slices thick enough to hold the garlic butter.',clip:'slice',clipLabel:'Slicing the bread',materials:['2 thick slices sourdough']},{title:'Make the garlic butter',description:'Mix 2 tbsp softened butter, 2 minced garlic cloves and 1 tbsp chopped parsley until evenly combined.',tip:'Let the garlic butter sit for a moment so the flavor blooms.',clip:'mix',clipLabel:'Make the garlic butter',materials:['2 tbsp softened butter','2 cloves garlic','1 tbsp parsley']},{title:'Spread generously',description:'Cover the bread right to the edges with the garlic butter.',tip:'Reach all the way to the corners for crisp, golden edges.',clip:'spread',clipLabel:'Spread the garlic butter',materials:['Prepared garlic butter','Sliced sourdough']},{title:'Bake until golden',description:'Bake until the edges are golden and the top is crisp.',tip:'Add the temperature before publishing so viewers can follow safely.',clip:'toast',clipLabel:'Bake until golden',materials:['Prepared toast','Oven temperature'],temperature:''},{title:'Serve warm',description:'Let it cool slightly, then enjoy.',tip:'Serve while the center is still soft and buttery.',clip:'finish',clipLabel:'Serve warm',materials:['Golden garlic toast']}];}
function servingValue(){return Math.max(1,Math.min(4,Number(state.recipe.servings)||2))}
function formatScaledIngredient(item){const value=(item.baseValue||0)*servingValue()/2;const number=Number.isInteger(value)?String(value):String(Number(value.toFixed(1)));return `${number} ${item.unit}`}
function updateServings(delta){const next=Math.max(1,Math.min(4,servingValue()+delta));state.recipe.servings=String(next);state.recipe.ingredients=state.recipe.ingredients.map((item,index)=>({...item,amount:formatScaledIngredient(state.initialRecipe.ingredients[index])}));render()}
function renderRecipeStatus(dark=false){return `<div class="recipe-status ${dark?'dark':''}"><span>9:41</span><span>▮▮▮ ◒ ▰</span></div>`}
function renderCreatorPublish(){return `<div class="screen-scroll creator-native figma-publish"><div class="publish-status"><span>9:41</span><span>▮▮▮ ◒ ▰</span></div><div class="publish-nav"><button class="nav-text-button nav-back" type="button" data-action="reset" aria-label="Close post composer">${icon('back')}</button><span></span><button class="nav-text-button nav-text-button-strong" type="button" data-action="publish-post">Post</button></div><section class="publish-media"><div class="publish-description"><textarea class="text-area" id="caption" data-edit="creatorCaption" placeholder="Add description...">${esc(state.creatorCaption||'My go-to garlic butter toast 🧄 #easyrecipe #homecooking')}</textarea><div class="publish-tags"><span># Hashtags</span><span>@ Mention</span></div></div><button class="cover-button" type="button"><span class="cover-image"></span><span>Edit cover</span></button></section><section class="publish-settings"><button class="publish-row" type="button"><span class="row-icon">⌖</span><span><strong>Add location</strong></span>${icon('arrow')}</button><button class="publish-row" type="button"><span class="row-icon">＋</span><span><strong>Add link</strong></span>${icon('arrow')}</button><button class="publish-row recipe-entry-row" type="button" data-action="${state.guideAttached?'edit-guide':'start-processing'}"><span class="row-icon">＋</span><span><strong>${state.guideAttached?'Recipe added':'Add recipe'}</strong><small>${state.guideAttached?'Viewers can follow along with this video':'Let viewers cook along with your video'}</small></span>${icon('arrow')}</button><button class="publish-row" type="button"><span class="row-icon">◉</span><span><strong>Everyone can view this post</strong></span>${icon('arrow')}</button><button class="publish-row" type="button"><span class="row-icon">•••</span><span><strong>More options</strong><small>Privacy and more settings</small></span>${icon('arrow')}</button><div class="publish-share-row"><span><strong>Share to</strong></span>${icon('arrow')}</div></section><div class="publish-footer"><button class="draft-button" type="button" data-action="back-to-creator">Drafts</button><button class="primary-button publish-submit" type="button" data-action="publish-post">Post</button></div></div>`}
function renderViewerVideo(){const entry=state.guideAttached?`<button class="cook-entry" type="button" data-action="open-guide"><span class="cook-entry-icon">☷</span><span>Cook with me</span><span>›</span></button>`:'';return `<section class="viewer-video figma-video"><div class="full-clip">${clipMarkup(state.recipe.steps[0])}</div><div class="video-topbar"><button class="video-live-button" type="button" data-action="reset" aria-label="Close video"><span class="live-dot"></span>LIVE</button><div class="video-tabs"><span>Following</span><strong>For You</strong></div><button class="video-search" type="button" aria-label="Search">⌕</button></div><div class="video-actions"><div class="video-action"><span class="circle creator-avatar"></span><span class="follow-plus">+</span></div><div class="video-action"><span class="circle">${icon('heart')}</span><span>3.1M</span></div><div class="video-action"><span class="circle">${icon('comment')}</span><span>45.4K</span></div><div class="video-action"><span class="circle rail-symbol">▯</span><span>233.8K</span></div><div class="video-action"><span class="circle">${icon('share')}</span><span>183.9K</span></div><div class="video-action sound-action"><span class="sound-disc">♫</span><span>original sound</span></div></div><div class="video-caption"><div class="video-author-line"><strong>${esc(state.recipe.creator)}</strong><span> · </span><span>Follow</span></div><p>${esc(state.recipe.description)} <strong>#easyrecipe #cookwithme</strong></p></div>${entry}<div class="video-bottom-nav"><span>⌂<small>Home</small></span><span>♧<small>Friends <b class="nav-badge">5</b></small></span><span class="create-pill">+</span><span>▢<small>Inbox <b class="nav-badge">23</b></small></span><span>◯<small>Profile</small></span></div><span class="home-indicator" aria-hidden="true"></span></section>`}
function renderOverview(){return `<div class="screen-scroll recipe-screen"><div class="recipe-hero"><div class="recipe-status"><span>9:41</span><span>▮▮▮ ◒ ▰</span></div><div class="recipe-hero-top"><button class="recipe-back" type="button" data-action="back-to-video" aria-label="Back to video">${icon('back')}</button><span></span><span></span></div><div class="recipe-hero-copy"><h1>${esc(state.recipe.title)}</h1><p>By ${esc(state.recipe.creator)}</p></div></div><section class="recipe-body"><button class="recipe-start" type="button" data-action="start-cooking">Start cooking</button><p class="recipe-description">Crisp edges, a soft middle, and plenty of garlic. A simple snack you can make in 15 minutes.</p><div class="recipe-stats"><span><strong>Total time</strong><b>${esc(state.recipe.time)}</b></span><span><strong>Servings</strong><b>${servingValue()} ${servingValue()===1?'person':'people'}</b></span></div><div class="recipe-section-head"><h2>Ingredients</h2><div class="servings-stepper"><button type="button" data-action="decrease-servings" aria-label="Decrease servings">−</button><span>${servingValue()} servings</span><button type="button" data-action="increase-servings" aria-label="Increase servings">+</button></div></div><div class="recipe-ingredients">${state.recipe.ingredients.map(item=>`<div class="recipe-ingredient"><span>${esc(item.amount.split(' ').slice(1).join(' ')||item.amount)}</span><b>${esc(item.amount.split(' ')[0])}</b></div>`).join('')}</div><span class="recipe-home-indicator" aria-hidden="true"></span></section></div>`}
function renderCookStepCard(step,index){const completed=index<state.viewerStep;return `<button type="button" class="cook-step-card ${completed?'is-complete':''} ${index===state.viewerStep?'is-active':''}" data-action="jump-step" data-step-index="${index}"><strong>${completed?'✓ ':''}${index+1} · ${esc(step.title)}</strong>${index===state.viewerStep?`<span>${esc(step.description)}</span>`:''}</button>`}
function renderExploreTimer(){return `<div class="explore-timer"><div class="timer-value">${formatTime(state.timerSeconds)}</div><div class="timer-status">${state.timerRunning?'remaining · 8-minute timer':state.timerSeconds===0?'Timer finished':'ready · 8-minute timer'}</div><div class="timer-actions"><button type="button" data-action="${state.timerRunning?'toggle-timer':'restart-timer'}">${state.timerRunning?'Pause timer':state.timerSeconds===0?'Restart timer':'Start timer'}</button><button type="button" data-action="reset-timer">Reset</button></div></div>`}
function renderIngredientsSheet(){return `<div class="ingredients-overlay"><button class="ingredients-scrim" type="button" data-action="close-ingredients" aria-label="Close ingredients"></button><section class="ingredients-sheet"><div class="sheet-handle"></div><div class="ingredients-sheet-head"><div><h2>Ingredients</h2><p>${esc(state.recipe.title)} · ${servingValue()} servings</p></div><button type="button" data-action="close-ingredients" aria-label="Close ingredients">×</button></div><div class="sheet-ingredient-list">${state.recipe.ingredients.map(item=>`<div class="sheet-ingredient"><strong>${esc(item.name)}</strong><span>${esc(item.amount)}</span></div>`).join('')}</div><p class="sheet-note">Your current step stays open underneath.</p><button class="sheet-back" type="button" data-action="close-ingredients">Back to cooking</button></section></div>`}
function renderCook(){const step=state.recipe.steps[state.viewerStep];return `<div class="screen-scroll cook-figma">${renderRecipeStatus()}<div class="cook-figma-top"><button type="button" data-action="back-to-overview" aria-label="Back to guide">${icon('back')}</button><strong>Follow along</strong><span></span></div><main class="cook-content"><h1 class="cook-recipe-title">${esc(state.recipe.title)} · ${servingValue()} servings</h1><div class="cook-step-label">Step ${state.viewerStep+1} of ${state.recipe.steps.length}</div><div class="cook-step-stack">${state.viewerStep===3?`${renderCookStepCard(state.recipe.steps[2],2)}${renderCookStepCard(step,3)}${renderExploreTimer()}${renderCookStepCard(state.recipe.steps[4],4)}<p class="timer-note">The timer keeps running while you check ingredients.</p>`:`${renderCookStepCard(step,state.viewerStep)}<div class="cook-media"><div class="cook-media-image" aria-label="Current step video · ${esc(step.title)}"></div><span class="cook-media-title">Current step video · ${esc(step.title)}</span><span class="cook-media-time">00:${String(state.viewerStep*8).padStart(2,'0')}–00:${String(state.viewerStep*8+8).padStart(2,'0')} · Tap to replay / loop</span><button class="cook-play" type="button" data-action="toggle-clip" aria-label="${state.clipPlaying?'Pause clip':'Play clip'}">${icon(state.clipPlaying?'pause':'play')}</button><button class="cook-replay" type="button" data-action="replay-clip">${icon('replay')} Replay</button></div><h2 class="your-steps-heading">Your steps</h2><div class="cook-step-list">${state.recipe.steps.map((item,index)=>renderCookStepCard(item,index)).join('')}</div>`}</div></main><div class="cook-figma-footer"><button type="button" class="ingredients-button" data-action="open-ingredients">Ingredients</button><button type="button" class="next-step-button" data-action="next-step">${state.viewerStep===state.recipe.steps.length-1?'Finish':'Next step'} ${icon('arrow')}</button></div>${state.ingredientsOpen?renderIngredientsSheet():''}</div>`}
function renderComplete(){return `<section class="complete-figma">${renderRecipeStatus()}<div class="complete-figma-top"><button type="button" data-action="back-to-video" aria-label="Back to video">${icon('back')}</button><span>Follow along</span><span></span></div><div class="complete-copy"><h1>You made it!</h1><p>One saved video. One real-life win.</p></div><div class="complete-image"></div><div class="complete-result-copy"><h2>Made it? Make it yours.</h2><p>Create a new TikTok post with your photo or video. The original recipe will be linked.</p></div><div class="complete-actions"><button type="button" class="complete-primary" data-action="share-result">Post your result</button><button type="button" class="complete-secondary" data-action="back-to-video">Back to video</button></div><span class="home-indicator" aria-hidden="true"></span></section>`}
function renderShare(){if(state.shareStage==='published')return `<section class="share-published"><div class="share-published-icon">✓</div><h1>Your result is live.</h1><p>New TikTok post published with “${esc(state.recipe.title)}” linked.</p><button type="button" class="complete-secondary" data-action="back-to-video">Back to video</button></section>`;if(state.shareStage==='picker')return `<section class="result-flow result-picker">${renderRecipeStatus()}<div class="result-top"><button type="button" data-action="back-to-complete">${icon('back')}</button><strong>Post your result</strong><span></span></div><h1>Choose a photo or video</h1><p>Select an example result to continue.</p><div class="result-media-grid">${[0,1].map(image=>`<button type="button" class="result-media ${state.shareImage===image?'is-selected':''}" data-action="select-share-image" data-share-image="${image}"><span class="result-media-image"></span><b>${image===0?'Photo':'Video'}</b>${state.shareImage===image?'<i>✓</i>':''}</button>`).join('')}</div><button type="button" class="result-primary" data-action="continue-share">Continue</button></section>`;if(state.shareStage==='preview')return `<section class="result-flow result-preview">${renderRecipeStatus()}<div class="result-top"><button type="button" data-action="back-to-share-picker">${icon('back')}</button><strong>Preview</strong><span></span></div><div class="result-large-image"></div><h1>Looks good.</h1><p>Your original recipe will be linked automatically.</p><button type="button" class="result-primary" data-action="continue-share-settings">Continue</button></section>`;return `<section class="result-flow result-settings">${renderRecipeStatus()}<div class="result-top"><button type="button" data-action="back-to-share-preview">${icon('back')}</button><strong>Post</strong><button type="button" data-action="publish-share">Post</button></div><div class="result-cover"><div class="result-large-image"></div><span>Edit cover</span></div><textarea class="result-caption" data-share-caption placeholder="Add a description...">${esc(state.shareCaption)}</textarea><div class="result-setting-row"><strong>Everyone can view this post</strong>${icon('arrow')}</div><div class="result-setting-row"><strong>Linked recipe</strong><span>${esc(state.recipe.title)}</span></div><p class="result-simulated">Your result will publish as a new TikTok post.</p><button type="button" class="result-primary" data-action="publish-share">Post</button></section>`}
function renderStepEditor(step,index){const missing=index===3&&!step.temperature;return `<article class="step-editor"><div class="step-editor-top"><span class="step-number">${index+1}</span><strong>Step ${index+1}</strong></div><div class="step-preview-row"><div class="mini-clip">${clipMarkup(step)}</div><span class="mini-clip-label">${esc(step.clipLabel)}<br />Matched from 0:${String(index*4).padStart(2,'0')}–0:${String(index*4+8).padStart(2,'0')}</span></div><label class="input-label" for="step-title-${index}">Step name</label><input class="text-input" id="step-title-${index}" data-step="${index}" data-key="title" value="${esc(step.title)}" /><label class="input-label" for="step-description-${index}">What to do</label><textarea class="text-area" id="step-description-${index}" data-step="${index}" data-key="description">${esc(step.description)}</textarea>${index===3?`<div class="needs-input"><div class="needs-input-head"><span></span>Needs your input</div><p>AI heard “bake until golden,” but the temperature is not in the video. Add it before publishing.</p><label class="input-label" for="temperature">Oven temperature</label><input class="text-input" id="temperature" data-step="${index}" data-key="temperature" placeholder="e.g. 200°C" value="${esc(step.temperature||'')}" />${state.editorError&&missing?'<p class="error-note">Add the oven temperature to continue.</p>':''}</div>`:''}</article>`}
function renderPosted(){return `<section class="posted-screen"><div class="posted-icon">${icon('check')}</div><div class="eyebrow" style="margin-top:1.4rem;color:var(--cyan)">Published · simulated</div><h1>${state.guideAttached?'Your guide is<br />in the post.':'Your video is<br />live.'}</h1><p>${state.guideAttached?'Viewers can now open “Cook with me” and cook through your steps at their own pace.':'This post has no recipe attached, so viewers will see the regular TikTok video experience.'}</p><div class="button-row"><button class="secondary-button" type="button" data-action="back-to-creator">Back to create</button><button class="primary-button" type="button" data-action="view-post"><span class="button-dot"></span>View post</button></div></section>`}

function handleClick(event){const modeButton=event.target.closest('[data-mode]');if(modeButton){state.mode=modeButton.dataset.mode;state.screen=state.mode==='creator'?'publish':'video';render();return}const action=event.target.closest('[data-action]');if(!action)return;const name=action.dataset.action;if(name==='reset')return reset();if(name==='start-processing')return startProcessing();if(name==='back-publish')return go('publish');if(name==='back-editor')return go('editor');if(name==='edit-guide')return go('editor');if(name==='preview-guide')return go('creator-preview');if(name==='remove-guide'){state.guideAttached=false;return render()}if(name==='confirm-guide')return confirmGuide();if(name==='publish-post')return publishPost();if(name==='back-to-creator'){state.mode='creator';return go('publish')}if(name==='view-post'){state.mode='viewer';return go('video')}if(name==='open-guide'){if(!state.guideAttached)return;state.mode='viewer';return go('overview')}if(name==='back-to-video'){state.mode='viewer';return go('video')}if(name==='back-to-overview')return go('overview');if(name==='start-cooking'){state.viewerStep=0;state.clipProgress=0;state.clipPlaying=true;return go('cook')}if(name==='toggle-clip'){state.clipPlaying=!state.clipPlaying;return render()}if(name==='replay-clip'){state.clipProgress=0;state.clipPlaying=true;return render()}if(name==='previous-step'){state.viewerStep=Math.max(0,state.viewerStep-1);state.clipProgress=0;state.clipPlaying=true;return render()}if(name==='next-step'){if(state.viewerStep>=state.recipe.steps.length-1){state.timerRunning=false;return go('complete')}state.viewerStep+=1;state.clipProgress=0;state.clipPlaying=true;return render()}if(name==='open-directory'){state.directoryOpen=true;return render()}if(name==='close-directory'){state.directoryOpen=false;return render()}if(name==='open-ingredients'){state.ingredientsOpen=true;return render()}if(name==='close-ingredients'){state.ingredientsOpen=false;return render()}if(name==='jump-step'){state.viewerStep=Number(action.dataset.stepIndex);state.directoryOpen=false;state.clipProgress=0;state.clipPlaying=true;return render()}if(name==='decrease-servings')return updateServings(-1);if(name==='increase-servings')return updateServings(1);if(name==='toggle-timer'){if(state.timerSeconds===0)return;state.timerRunning=!state.timerRunning;return render()}if(name==='reset-timer'){state.timerSeconds=480;state.timerRunning=false;return render()}if(name==='restart-timer'){state.timerSeconds=480;state.timerRunning=true;return render()}if(name==='share-result'){state.sharePublished=false;state.shareStage='picker';return go('share')}if(name==='back-to-complete')return go('complete');if(name==='back-to-share-picker'){state.shareStage='picker';return render()}if(name==='continue-share'){state.shareStage='preview';return render()}if(name==='continue-share-settings'){state.shareStage='settings';return render()}if(name==='back-to-share-preview'){state.shareStage='preview';return render()}if(name==='select-share-image'){state.shareImage=Number(action.dataset.shareImage);return render()}if(name==='publish-share'){state.sharePublished=true;state.shareStage='published';return render()}}
function handleInput(event){const el=event.target;if(el.dataset.shareCaption!==undefined){state.shareCaption=el.value;return}if(el.dataset.edit==='creatorCaption'){state.creatorCaption=el.value;return}if(el.dataset.edit)state.recipe[el.dataset.edit]=el.value;if(el.dataset.ingredient!==undefined)state.recipe.ingredients[Number(el.dataset.ingredient)][el.dataset.key]=el.value;if(el.dataset.step!==undefined){state.recipe.steps[Number(el.dataset.step)][el.dataset.key]=el.value;if(el.dataset.key==='temperature')state.editorError=false}}
function go(screen){state.screen=screen;state.directoryOpen=false;state.ingredientsOpen=false;render()}
function confirmGuide(){const temperature=state.recipe.steps[3]?.temperature;if(!temperature||!temperature.trim()){state.editorError=true;state.screen='editor';render();setTimeout(()=>document.querySelector('#temperature')?.focus(),0);return}state.editorError=false;state.guideAttached=true;state.screen='publish';render();setTimeout(()=>toast('Recipe added — ready to post.'),0)}
function startCookingTimer(){clearInterval(cookingTimer);cookingTimer=setInterval(()=>{if(!state.timerRunning||state.timerSeconds<=0)return;state.timerSeconds-=1;if(state.timerSeconds<=0){state.timerSeconds=0;state.timerRunning=false}const timer=document.querySelector('.timer-value');const status=document.querySelector('.timer-status');if(timer)timer.textContent=formatTime(state.timerSeconds);if(status)status.textContent=state.timerRunning?'remaining · 8-minute timer':state.timerSeconds===0?'Timer finished':'ready · 8-minute timer'},1000)}
function reset(){clearTimeout(processTimer);stopClipTimer();stopCookingTimer();state.mode='creator';state.screen='publish';state.recipe=clone(state.initialRecipe);state.guideAttached=false;state.processingStep=0;state.viewerStep=0;state.checkedIngredients=new Set();state.clipPlaying=true;state.clipProgress=0;state.directoryOpen=false;state.ingredientsOpen=false;state.timerSeconds=480;state.timerRunning=false;state.shareImage=0;state.sharePublished=false;state.shareStage='picker';state.shareCaption='Made it through the Cook with me guide ✨';state.creatorCaption='My go-to garlic butter toast 🧄 #easyrecipe #homecooking';state.editorError=false;render()}
function renderExploreTimer(){const action=state.timerRunning?'toggle-timer':state.timerSeconds===0?'restart-timer':'toggle-timer';const label=state.timerRunning?'Pause timer':state.timerSeconds===0?'Restart timer':state.timerSeconds<480?'Resume timer':'Start timer';const status=state.timerRunning?'remaining · 8-minute timer':state.timerSeconds===0?'Timer finished':state.timerSeconds<480?'Timer paused. Resume when you’re ready.':'ready · 8-minute timer';return `<div class="explore-timer"><div class="timer-value">${formatTime(state.timerSeconds)}</div><div class="timer-status">${status}</div><div class="timer-actions"><button type="button" data-action="${action}">${label}</button><button type="button" data-action="reset-timer">Reset</button></div></div>`}
function renderOverview(){return `<div class="screen-scroll recipe-screen"><div class="recipe-hero"><div class="recipe-status"><span>9:41</span><span>▮▮▮ ◒ ▰</span></div><div class="recipe-hero-top"><button class="recipe-back" type="button" data-action="back-to-video" aria-label="Back to video">${icon('back')}</button><span></span><span></span></div><div class="recipe-hero-copy"><h1>${esc(state.recipe.title)}</h1><p>By ${esc(state.recipe.creator)}</p></div></div><section class="recipe-body"><button class="recipe-start" type="button" data-action="start-cooking">Start cooking</button><p class="recipe-description">Crisp edges, a soft middle, and plenty of garlic. A simple snack you can make in 15 minutes.</p><div class="recipe-stats"><span><strong>Total time</strong><b>${esc(state.recipe.time)}</b></span><span><strong>Servings</strong><b>${servingValue()} ${servingValue()===1?'person':'people'}</b></span></div><div class="recipe-section-head"><h2>Ingredients</h2><div class="servings-stepper"><button type="button" data-action="decrease-servings" aria-label="Decrease servings">−</button><span>${servingValue()} servings</span><button type="button" data-action="increase-servings" aria-label="Increase servings">+</button></div></div><div class="recipe-ingredients">${state.recipe.ingredients.map(item=>`<div class="recipe-ingredient"><span>${esc(item.amount)} ${esc(item.name.toLowerCase())}</span></div>`).join('')}</div><span class="recipe-home-indicator" aria-hidden="true"></span></section></div>`}
